/* Runvis homepage translations — Spanish. One language per file so a
   visitor downloads 1/6 of the dictionary, not all of it. i18n.js
   injects exactly the file it needs and calls RunvisOnDict when it lands. */
(window.RUNVIS_I18N=window.RUNVIS_I18N||{})["es"]={"a11y.langmenu": "Idioma", "a11y.langname": "Español", "a11y.playing": "Sonando la voz de ejemplo", "a11y.skip": "Saltar al contenido", "a11y.stopped": "Reproducción detenida", "a11y.wspause": "Pausar el cambio automático", "a11y.wsplay": "Activar el cambio automático", "alt.phone.detail": "Detalle de una métrica en el iPhone: tendencia de 7 días de la carga de entrenamiento (CTL), tu rango de 28 días y la explicación de la métrica", "alt.phone.glance": "Parte baja del Informe cuerpo y running en el iPhone: paneles de Volumen de entrenamiento de resistencia 66/100, Exposición a cuestas y exposición al calor (aún en «Aprendiendo»), Freno del coach, Radar de récords del coach con tus mejores tramos de 1K a media maratón, Reparto de intensidad y Carga en las piernas", "alt.phone.hero": "Inicio en el iPhone: la decisión de hoy es descansar (descanso total o un paseo suave)", "alt.phone.plan": "Plan de entrenamiento semanal en el iPhone", "alt.phone.race": "Predicción de carrera en el iPhone", "alt.watch.decision": "Apple Watch Ultra con Runvis, Decisión de hoy: anillo de preparación y día de descanso", "alt.watch.evidence": "Apple Watch Ultra con Runvis, Evidencia de hoy: sueño y VFC", "alt.watch.map": "Apple Watch Ultra con Runvis en plena carrera: mapa GPS en directo con distancia, tiempo y ritmo", "alt.watch.pace": "Apple Watch Ultra con Runvis en plena carrera: ritmo actual, ritmo medio, velocidad, GAP y pendiente", "alt.watch.start": "Apple Watch Ultra con Runvis: lista de entrenos para empezar, con Carrera y Carrera indoor", "alt.watch.zone": "Apple Watch Ultra con Runvis: arco de zonas de FC", "cs.marketing": "(Opcional) Acepto recibir novedades del lanzamiento y actualizaciones.", "cs.purpose": ": enviarte la invitación a la beta de TestFlight", "cs.retain": ": se elimina sin demora en cuanto se cumple la finalidad (enviada la invitación a la beta) y, en todo caso, en el plazo de un año desde su recogida", "form.busy": "Aún estamos preparando las inscripciones. Espera un momento.", "form.fail": "No se ha podido enviar. Vuelve a intentarlo en un rato.", "form.mailto": "Apúntate por correo: help@runvis.app", "form.neterr": "Error de red. Vuelve a intentarlo en un rato.", "form.novoice": "Este navegador no puede reproducir la voz.", "form.ok": "Listo, inscripción hecha. Cuando haya fecha de apertura te avisaremos en esta dirección, y cuando abra la beta mandaremos las invitaciones por orden de inscripción. No enviamos correo de confirmación, así que comprueba que la dirección de arriba está bien. Si quieres que la borremos, escríbenos cuando quieras a help@runvis.app. Mientras tanto, corre la demo de 5 km. 🏃", "form.okcta": "Corre la demo de 5 km", "form.sending": "Enviando…", "gpx.ansan": "Sendero Jarak del Ansan", "gpx.banpo": "Parque del río Han en Banpo", "gpx.bukak": "Bugak Skyway", "gpx.cheonggyecheon": "Arroyo Cheonggyecheon", "gpx.dorimcheon": "Arroyo Dorimcheon", "gpx.eungbong": "Escaleras del Eungbongsan", "gpx.inwangsan": "Sendero Jarak del Inwangsan", "gpx.naksan": "Muralla de Seúl, parque Naksan", "gpx.namsan.north": "Namsan, circuito norte", "gpx.namsan.summit": "Subida a la cima del Namsan", "gpx.seoulsup": "Circuito del Bosque de Seúl", "gpx.tancheon": "Arroyo Tancheon", "gpx.yangjaecheon": "Arroyo Yangjaecheon", "hero0": "Ahora mismo hace 3 grados con un 60 por ciento de humedad. Hace frío y los músculos se agarrotan con facilidad, así que hoy calentaremos un poco más de lo habitual.", "hero1": "En 300 metros empieza una subida de 800 metros. Pendiente media del 4 por ciento. Acorta la zancada y mantén el ritmo.", "hero2": "25 segundos más rápido que el objetivo", "hero3": "Tu pulso ha bajado a la zona 3. Te estás recuperando bien. Un poco más.", "hw.vs.cap1": "Así se ve en la app la primera fila de la tabla: la tendencia de 7 días de la carga de entrenamiento (CTL), tu rango de 28 días y qué significa esa métrica.", "hw.vs.cap2": "Y así, la cuarta fila: predicción de carrera y plan de ritmos por tramo.", "hw.vs.r0a": "¿Qué más hay que comprar?", "hw.vs.r0b": "Con Garmin Forerunner o Coros, lo que compras es el reloj. Runvis usa el Apple Watch que ya llevas: lo único que pagas aparte es la suscripción al coach.", "hw.vs.r10a": "Freno del coach", "hw.vs.r10b": "No es una nota, es un presupuesto. Con tu distancia semanal de las últimas 4 semanas (solo semanas completas) calcula cuántos kilómetros puedes asumir esta semana, y los recorta según el dolor que anotes después de correr. Te enseña por separado los kilómetros que te quedan y los que ha quitado el dolor, así ves al momento por qué ha bajado.", "hw.vs.r11a": "Radar de récords del coach", "hw.vs.r11b": "En las carreras con ruta GPS repasa el registro entero y encuentra tu tramo más rápido (mejor esfuerzo). En las que no tienen ruta, lo calcula con el ritmo medio de toda la carrera. La pantalla indica de qué forma se obtuvo cada marca. Tiene en cuenta los últimos 90 días.", "hw.vs.r7a": "Reparto de intensidad", "hw.vs.r7b": "Si la carrera tiene registro de pulso y tu FC máxima es un valor medido de verdad, reparte el tiempo en tres franjas (suave, media y fuerte), con los cortes en el 78% y el 88% de la máxima. Si no hay registro de pulso o la máxima solo sale de la fórmula por edad, la franja la decide el pulso medio de esa carrera, y una sesión de series puede acabar metida entera en intensidad media. La pantalla indica qué método se ha usado.", "hw.vs.r8a": "Exposición a cuestas", "hw.vs.r8b": "Toma solo las carreras con subida de los últimos 28 días (hacen falta al menos 2) y divide el desnivel positivo total entre la distancia total (m/km). Desde 15, terreno ondulado; desde 40, recorridos con muchas cuestas. No puntúa al corredor: registra el terreno por el que has corrido.", "hw.vs.r9a": "Índice de exposición al calor", "hw.vs.r9b": "De 0 a 100, cuánto has corrido al aire libre en días por encima de 22 °C durante las últimas 4 semanas (si usas Fahrenheit, la misma temperatura en °F). Aparece tras 3 carreras con calor y baja si pasas 3 días o más sin correr. Mide cuánto calor has pasado, no cuánto se ha adaptado tu cuerpo.", "hw.vs.tm": "Garmin, Forerunner y COROS son marcas de sus respectivas empresas. Runvis no tiene relación con ninguna de las dos. Aquí solo hay datos públicos: ninguna de las dos publica sus fórmulas, así que no comparamos la precisión.", "hz.cap": "Así dibuja el reloj, mientras corres, las mismas zonas que te da la calculadora de abajo.", "meta.desc": "Sin comprar otro reloj: el Apple Watch que ya llevas se convierte en tu entrenador de running. Lee tu sueño y tu pulso para decidir el entreno de hoy, y mientras corres te habla solo cuando hace falta. Sin cuenta y sin servidores.", "meta.ogdesc": "El Apple Watch que ya llevas, convertido en tu entrenador de running. El entreno de hoy, por la mañana. La frase justa, mientras corres.", "meta.ogalt": "Tarjeta de Runvis — You run. We coach.", "meta.ogtitle": "Runvis — entrenador de running para Apple Watch", "meta.title": "Runvis — You run. We coach. Entrenador de running para Apple Watch", "n.after.eb": "Después de correr", "n.after.h2": "Cuando terminas,<br/>ves el porqué, no solo la cifra", "n.after.h3": "Toca una métrica y la ves junto a tu rango habitual", "n.after.honest": "<b>Lo estimado lleva la etiqueta «estimado».</b> Si faltan datos, verás «Aprendiendo» en vez de un número. Y lo que no podemos respaldar, directamente no está en la app.", "n.after.l1": "Carga de entrenamiento, ACWR y tiempo de recuperación, calculados con fórmulas publicadas", "n.after.l2": "Desde el detalle del entreno exportas un informe para análisis con IA y lo pegas en la IA que uses", "n.after.l3": "Exportación a GPX y vídeo de sobrevuelo en 3D de tu ruta", "n.after.p": "De un vistazo ves si el valor de hoy está dentro de tu rango habitual de los últimos 28 días y cómo está frente a hace 4 semanas. No hace falta saberse los términos: cada métrica trae qué significa y de dónde sale.", "n.after.sub": "Parciales, zonas de FC, dinámica de carrera y la frase del coach: gratis. Con la suscripción sumas el Radar de récords del coach, que encuentra tu tramo más rápido dentro de cada carrera, la estimación del umbral de lactato y tu presupuesto de kilómetros para la semana.", "n.after.t1": "Informe detallado del entreno", "n.after.t1p": "Ritmo por tramos, reparto por zonas de FC, cadencia y tiempo de contacto medios. Y una frase del coach sobre esta carrera.", "n.after.t2": "Informe del cuerpo", "n.after.t2p": "Preparación, sueño, VFC, FC en reposo y VO₂max. Toca y se abren la gráfica de tendencia y tu rango habitual de 28 días.", "n.after.t3": "Radar de récords del coach (tramos más rápidos · tus mejores marcas)", "n.after.t3p": "No mira tu tiempo final: busca en tus carreras de los últimos 90 días el tramo más rápido de 1K, 5K, 10K y media maratón. Y te enseña la diferencia con tu marca anterior.", "n.after.t4": "Umbral de lactato estimado", "n.after.t4p": "Busca en tus carreras de los últimos 90 días tus mejores tramos de 30 minutos (necesita al menos 2) y con ellos estima tu ritmo y tu pulso de umbral. Si has introducido tu FC máxima, solo cuentan los tramos aguantados al 85% o más de esa máxima.", "n.after.t4h": "¿Y si no tengo ningún tramo de 30 minutos?", "n.after.t4g": "Si no hay tramo de 30 minutos, usa uno de 20. Si tampoco lo hay, lo estima con la media de tres carreras de 20 minutos o más al 85% o más de tu FC máxima; para eso necesitas haber introducido la máxima. La pantalla siempre indica qué método se ha usado.", "a11y.watchstack": "3 pantallas del Apple Watch en plena carrera, que se van alternando", "n.after.t5": "Freno del coach", "n.after.t5p": "Con tu volumen de las últimas 4 semanas fija tu presupuesto de kilómetros para esta semana. Si dices que te duele algo, lo recorta.", "n.after.t6": "Índice de forma de Runvis", "n.after.t6p": "Calcula tu índice de forma a partir de tus mejores esfuerzos y, con él, predice tus marcas en cada distancia. Puedes verlo al lado del VO₂max de tu Apple Watch.", "n.beta.cta2": "Avísame cuando salga", "n.beta.eb": "Apúntate a la beta", "n.beta.gpx": "Los archivos GPX de los 13 recorridos de Seúl que usa la app. Sin apuntarte y sin instalar la app: descárgalos ya y ábrelos en otro reloj o en tu app de mapas. Las distancias están en km en los 6 idiomas. Un archivo GPX no lleva unidades; si usas millas, tu dispositivo hace la conversión solo.", "n.beta.gpxattr": "Trazados a partir de datos de carreteras y senderos de OpenStreetMap; altitud de Copernicus DEM / NASA SRTMGL1 (dominio público). © OpenStreetMap contributors · ODbL 1.0.", "n.beta.gpxh": "Si corres por Seúl: 13 recorridos en GPX", "n.beta.h2": "Pruébalo antes de que salga", "n.beta.nowh": "Qué puedes hacer mientras esperas", "n.beta.required": "(Obligatorio) Acepto que se recoja y use mi correo para enviarme la invitación a la beta.", "n.beta.s1": "Inscripción: solo te pedimos el correo. No hay que crear ninguna cuenta.", "n.beta.s2": "Invitación de TestFlight: cuando abra la beta, mandamos los enlaces por orden de inscripción. Apple pone un tope de 10.000 probadores externos y solo necesitas una cuenta de Apple. No pagas nada: en la versión beta, todas las funciones del coach son gratis mientras dure. Si no aceptaste recibir comunicaciones comerciales, no te llegará nada más que esa invitación.", "n.beta.s3": "Comentarios: mándalos desde la propia app o a help@runvis.app.", "n.beta.s4": "Lanzamiento: la fecha se decide cuando acabe la beta. Sale primero en el App Store de Corea y después, poco a poco, en el resto de países.", "n.beta.stepsh": "Qué pasa cuando te apuntas", "n.beta.sub": "Déjanos tu correo y, cuando abra la beta de TestFlight, te mandamos una invitación. Cuando haya fecha de apertura, la publicaremos primero aquí y también te avisaremos en esa dirección.", "n.beta.want": "¿Qué quieres recibir?", "n.beta.want1": "Entrar en la beta: quiero la invitación de TestFlight", "n.beta.want2": "Solo el aviso de lanzamiento: avísame una vez, cuando salga", "n.beta.do1": "<a href=\"run.html\">Demo de 5 km</a>: escucha cuándo habla el coach y cuándo se calla, y dónde acaba la voz gratis y empieza la de la suscripción.", "n.beta.do2": "<a href=\"how-it-works.html#zones\">Calculadora de zonas de FC</a>: calcula tus 5 zonas con la misma fórmula de Karvonen que usa la voz del coach. Solo necesitas tu edad y tu FC en reposo.", "n.beta.do3": "<a href=\"how-it-works.html#gpx\">13 recorridos de Seúl en GPX</a>: descárgalos ya, sin instalar la app, y ábrelos en tu reloj o tu app de mapas de siempre.", "n.beta.do4": "<a href=\"how-it-works.html#beta\">Cómo va la beta</a>: cuatro pasos, inscripción · invitación de TestFlight · comentarios · lanzamiento. En la versión beta, todas las funciones del coach son gratis mientras dure.", "n.beta.do5": "<a href=\"privacy.html\">Política de privacidad</a>: todo lo que recoge este formulario y todo lo que la app envía fuera del dispositivo, sin dejarse nada.", "n.faq.a1": "Sí. Solo con el iPhone grabas por GPS y, cada 1 km (o cada 1 milla, si usas millas), oyes el ritmo de ese parcial. Sin suscripción y solo con el iPhone, esa es la única voz que oirás. Con suscripción, el iPhone también te avisa del ritmo. Los avisos de zona de FC solo llegan si conectas una banda de pulso Bluetooth (una cinta BLE estándar como la Polar H10 o la Wahoo TICKR), porque el iPhone no tiene sensor de pulso. El coaching de técnica, el aviso de cuestas y la alerta de desvío de ruta solo funcionan si corres con el reloj.", "n.faq.a2": "Con watchOS 10 o posterior (Apple Watch Series 4 o posterior) e iOS 17 o posterior te vale. Basta con pulso y GPS. En los modelos recientes, que miden el tiempo de contacto y la oscilación vertical, el coaching de técnica afina más. En los que no miden esos dos valores, se guía por la cadencia.", "n.faq.a3": "Tus carreras siguen en Salud, tal cual. Aunque canceles, puedes seguir grabando, viendo el plan y consultando el informe detallado del entreno, gratis.", "n.faq.a6": "Sí. Haz una vez el Test de 12 min con el reloj y ese mismo día tienes tus tiempos estimados de 5K y 10K y tu primer plan. Este test solo se puede hacer con el reloj. Si solo tienes iPhone, desde el primer día puedes grabar por GPS, oír el ritmo de cada parcial y ver el plan de entrenamiento, que arranca de tu distancia semanal reciente. La preparación necesita acumular noches durmiendo con el reloj, así que suele tardar unas 2 semanas; el ACWR, unas 4. La Eficiencia frente a tu base aparece cuando has introducido tu FC máxima y sumas 3 carreras de más de 10 minutos con pulso registrado a la misma intensidad (suave, media o fuerte). Las primeras veces se compara con una línea base que aún no distingue la intensidad ni el momento de la medición, y la pantalla también te lo dice.", "n.faq.a8": "El acceso de por vida es un pago único, sin renovación automática. Frente al anual se amortiza en unos 2,6 años y frente al mensual en unos 20 meses: si piensas usarlo más tiempo, te sale más barato. Además, es el único plan compatible con Compartir en familia de Apple; las suscripciones mensual y anual no lo son.", "n.faq.a9": "Tus carreras están guardadas en Salud, así que la app Salud del dispositivo nuevo las recupera tal cual. Lo que solo estaba dentro de Runvis (tu perfil, las zonas de FC, tu lista de zapatillas y las líneas base que ha ido construyendo el coach) lo guardas en un solo archivo desde Ajustes → Datos → «Exportar mis datos» y lo recuperas en el dispositivo nuevo con «Restaurar desde una copia». Ese archivo solo está donde tú lo guardes; Runvis no lo envía a ningún sitio. La suscripción la recuperas con «Restaurar compras» del App Store.", "n.faq.eb": "Preguntas frecuentes", "n.faq.h2": "Lo que te preguntarás antes de empezar", "n.faq.q1": "¿Puedo usarlo sin reloj?", "n.faq.q2": "¿Qué Apple Watch necesito?", "n.faq.q3": "¿Qué pasa con mis carreras si cancelo?", "n.faq.q6": "¿Puedo empezar sin ningún historial?", "n.faq.q8": "¿Qué me sale más a cuenta, el acceso de por vida o el anual?", "n.faq.q9": "¿Y si cambio de dispositivo?", "n.hero.b5": "Grabar es gratis · unos 1,30 €/mes", "n.hero.b5n": "₩1,900/mes", "n.hero.cta1": "Apúntate a la beta", "n.hero.cta2": "Corre la demo de 5 km", "n.hero.eb": "Entrenador de running para Apple Watch", "n.hero.h1": "You run.<br/><span class=\"grad\">We coach.</span>", "n.hero.tag": "Already on your wrist.", "n.hero.note": "Te basta con un Apple Watch Series 4 o posterior y un iPhone. Grabar es gratis; solo el coach va por suscripción. Sale primero en el App Store de Corea y luego, poco a poco, en el resto de países.", "n.hero.sub": "¿Hoy toca correr o descansar? Abres la app por la mañana y ya está decidido. Runvis elige el entreno de hoy con el sueño y el pulso que registra tu Apple Watch, y mientras corres solo te habla cuando de verdad hace falta.", "n.live.demo": "Escucha en la demo de 5 km cuándo habla el coach y cuándo se calla", "n.live.eb": "Mientras corres", "n.live.h2": "Lo justo,<br/>en el momento justo", "n.live.q.n1": "Entre aviso y aviso pasan al menos 45 segundos. Los avisos clave, como los de seguridad o el cambio de fase del entrenamiento, y los parciales no esperan: suenan al momento. Abajo tienes el resto de excepciones.", "n.live.q.n2": "Los parciales, el aviso de cuesta y los avisos de pausa y reanudación automáticas siguen sus propias reglas, así que no cuentan para el tope de 30 minutos. El aviso de cambio entre andar y correr y la cuenta de respiración solo sirven si llegan a tiempo: por eso tampoco esperan los 45 segundos. Y lo mismo con el saludo que te da cuando reconoce un recorrido que ya hiciste.", "n.live.q.n3": "Si corres solo con el iPhone, las reglas cambian. Hay menos tipos de aviso, así que el intervalo mínimo baja a 20 segundos; el ritmo se avisa como mucho una vez cada 3 minutos, y la zona de FC, una vez cada 5. No hay tope de 30 minutos.", "n.live.q.n4": "Puedes activar o desactivar 8 avisos: Ritmo, Zonas de FC, Técnica, Cuestas, Ánimo y guion, Tarjeta de dato de running, Hidratación y avituallamiento y Voz de pausa y reanudación. Los parciales no tienen interruptor: eliges cada cuánto suenan (Desactivado, 0,5 o 1, en km o en millas). Los avisos de seguridad y los de fase del entrenamiento no se pueden apagar. La música baja un poco solo mientras habla el coach.", "n.live.q.r1a": "Rodaje suave · tirada larga · correr y caminar alternando", "n.live.q.r1b": "Hasta 8", "n.live.q.r2a": "Tempo · competición · carrera libre", "n.live.q.r2b": "Hasta 6", "n.live.q.r3a": "Series", "n.live.q.r3b": "Sin límite de avisos. A cambio, en las series solo suenan la fase del entrenamiento, la zona de FC, el ritmo y la pausa automática; parciales, cuestas, técnica y ánimo se callan", "n.live.q.th1": "Tipo de sesión", "n.live.q.th2": "Otros avisos cada 30 min (sin contar parciales, cuestas ni pausas)", "n.live.siri": "Di «Oye Siri, empezar a correr con Runvis» y se abre al momento la pantalla de inicio de carrera. Funciona en los 6 idiomas.", "n.live.sub": "Todo lo que dice el coach responde a algo que han captado los sensores. Toca y escucha los avisos reales.", "n.nav.after": "Después", "n.nav.cta": "Apúntate a la beta", "n.nav.demo": "Demo 5 km", "n.nav.faq": "FAQ", "n.nav.live": "Mientras corres", "n.nav.price": "Precio", "n.nav.race": "Competición", "n.nav.today": "Hoy", "n.nav.why": "Por qué Runvis", "n.paths.c1h": "Acabo de empezar a correr", "n.paths.c1p": "Lo primero: si hoy toca correr o descansar. La Decisión de hoy, a partir de tu sueño, tu VFC y la carga de ayer.", "n.paths.c2h": "Corro con regularidad, pero sin entrenador", "n.paths.c2p": "Un coach que, mientras corres, te habla de ritmo, cuestas y técnica.", "n.paths.c3h": "Estoy preparando una carrera", "n.paths.c3p": "Predicción de tu tiempo final y estrategia de ritmo por tramos, con el pronóstico del día de la carrera metido en el cálculo.", "n.paths.c4h": "Quiero bajar mis marcas", "n.paths.c4p": "Umbral de lactato, reparto de intensidad, volumen de entrenamiento de resistencia: mira qué mide cada métrica de pago.", "n.paths.eb": "Por dónde empezar", "n.paths.h2": "¿Qué tipo de runner eres?", "n.paths.j1": "Primero, el precio", "n.paths.j2": "Primero, adónde van mis datos", "n.paths.sub": "Elige la opción que más se parezca a ti ahora mismo y te llevamos directo a lo que te interesa.", "n.pill.free": "Gratis", "n.pill.pro": "Suscripción", "n.price.cancel": "Puedes cancelar cuando quieras desde los ajustes de tu cuenta del App Store. Si cancelas, sigues teniendo acceso hasta que acabe el periodo pagado y, a partir de ahí, deja de renovarse. Los reembolsos siguen la política de Apple.", "n.price.cta": "Pruébalo en la beta antes de que salga, o recibe solo el aviso de lanzamiento", "n.price.eb": "Precio", "n.price.f1": "Grabación GPS, ritmo, pulso, vueltas y guardado en Salud", "n.price.f2": "Informe detallado del entreno, informe del cuerpo e historial", "n.price.f3": "Ver el plan de entrenamiento, predicción de carrera básica, briefing del tiempo y pantalla de calentamiento, Modo carrera en el reloj y el fantasma de tu mejor marca", "n.price.f4": "Corriendo con el reloj: voz de parciales (en la unidad de tu dispositivo), zonas de FC, ritmo, aviso de cuestas y alerta de desvío de ruta", "n.price.f4b": "Solo con el iPhone, la única voz gratis son los parciales", "n.price.f5": "Exportación a GPX e informe para análisis con IA", "n.price.freeName": "Básico", "n.price.freecta": "Comprueba en la demo de 5 km hasta dónde llega lo gratis", "n.price.gateh": "¿Cuándo aparecen las cifras?", "n.price.gatelead": "Los 8 paneles se abren en cuanto pagas, y las cifras se van completando a medida que acumulas carreras. Hasta entonces, cada panel te dice qué le falta.", "n.price.g1": "Umbral de lactato (est.): 2 tramos de 30 minutos (o de 20) aguantados al 85% o más de tu FC máxima. Si solo tienes carreras sin ruta, se calcula con tu FC máxima introducida + 3 carreras de 20 minutos o más.", "n.price.g2": "Volumen de entrenamiento de resistencia: 6 carreras o más repartidas en 3 de las últimas 4 semanas (con al menos 2 semanas entre la primera y la última).", "n.price.g3": "Exposición a cuestas: 2 carreras con subida.", "n.price.g4": "Índice de exposición al calor: 3 carreras en días de más de 22 °C.", "n.price.g5": "Reparto de intensidad: 8 días de datos que incluyan 5 carreras con pulso registrado.", "n.price.g6": "Freno del coach: 2 semanas de carreras.", "n.price.g7": "Radar de récords del coach: empieza a guardar marcas con una sola carrera de 1 km o más.", "n.price.g8": "Carga en las piernas: basta con 1 carrera que tenga distancia registrada.", "n.price.h2": "Grabar es gratis.<br/>El coach, ₩1,900 al mes", "n.price.life": "Si prefieres no suscribirte: <b>acceso de por vida por ₩39,000</b>. Es precio de lanzamiento, y si más adelante sube, a quien ya lo compró no le afecta. Con los precios del App Store de Corea, se amortiza en unos 2,6 años frente al anual de ₩15,000, o en unos 20 meses frente al mensual de ₩1,900. Es el único plan que funciona con Compartir en familia de Apple.", "n.price.p1": "La voz del coach mientras corres: técnica, cómo subir las cuestas, recuperación y ánimo", "n.price.p2": "El plan, en marcha: el coach te guía tramo a tramo y al acabar te puntúa frente al plan", "n.price.p3": "Se desbloquean 8 paneles de análisis a fondo en el informe", "n.price.p4": "Estrategia de carrera: plan de ritmos por tramo, plan de avituallamiento y ensayo de carrera", "n.price.p5": "Tarjeta «Tu semana con el coach»: tu puntuación frente al plan, tu tramo más rápido de la semana, los kilómetros que te quedan en el presupuesto, el reparto de intensidad de las últimas 4 semanas y una cosa que cambiar la semana que viene. En la versión gratis la ves como vista previa bloqueada.", "n.price.p6": "El índice de forma de Runvis, calculado con tus mejores esfuerzos, predice tus marcas del 5K al maratón", "n.price.t1": "Umbral de lactato (est.)", "n.price.t2": "Volumen de entrenamiento de resistencia", "n.price.t3": "Exposición a cuestas", "n.price.t4": "Índice de exposición al calor", "n.price.t5": "Freno del coach", "n.price.t6": "Reparto de intensidad", "n.price.t7": "Radar de récords del coach (tramos más rápidos, últimos 90 días)", "n.price.t8": "Carga en las piernas", "n.price.sub": "Grabar, ver el plan y consultar los informes es gratis. La suscripción es para lo que hace el coach: hablarte y analizar por ti. Si el App Store considera que tu cuenta tiene derecho a la prueba, puedes probarlo gratis 1 mes. En el mensual y en el anual el periodo gratis es el mismo: 1 mes.", "n.price.year": "El anual cuesta <b>₩15,000</b>: en el App Store de Corea sale a unos ₩1,250 al mes, alrededor de un 34% menos que el mensual. En otros países los tramos de precio son distintos y el porcentaje puede cambiar, así que el ahorro real te lo calcula la pantalla de compra de la app con los precios de tu país. Si tu cuenta tiene derecho a prueba, el anual también la incluye, pero es de 1 mes, igual que el mensual. No de 1 año. Pasado ese mes, se cobran de una vez los ₩15,000 del año.", "n.priv.big": "Sin cuenta. Sin servidores.<br/>El coach te habla hasta dentro de un túnel.", "n.priv.eb": "Privacidad", "n.priv.link": "Política de privacidad", "n.priv.p": "La grabación y el análisis ocurren siempre dentro del reloj y del iPhone. Lo único que sale es esto: coordenadas redondeadas a aproximadamente 1 km cuando se consulta el tiempo; tus coordenadas de ese momento, enviadas a servicios de Apple para mostrar el nombre del barrio y generar rutas automáticamente; los pagos del App Store, y la descarga de los archivos públicos de recorridos y de zapatillas. Además, por ahora solo en el App Store de Corea, se abre una página externa de búsqueda de zapatillas únicamente si la tocas tú en la pantalla de zapatillas del reloj o del iPhone. Todas las excepciones están en la política de privacidad, sin dejarse ninguna. Tus datos de entreno y de salud no se suben a ningún sitio.", "n.race.eb": "Preparar una carrera", "n.race.h2": "Un plan semana a semana,<br/>y el día de la carrera, estrategia por tramos", "n.race.h3": "Según el coach que elijas, cambian el plan y el tono", "n.race.h3b": "Un coach que ya se sabe el recorrido", "n.race.l1": "En las series, el coach te guía en cada tramo y al terminar te puntúa frente al plan", "n.race.l2": "¿Día flojo? Con un toque baja la intensidad y te rehace la sesión", "n.race.l3": "¿Sin marcas previas? No pasa nada: con un Test de 12 min en el reloj ya tienes tu primer plan", "n.race.lb1": "Con una sola marca reciente: tiempos estimados de 5K, 10K, media y maratón, y tu ritmo objetivo", "n.race.lb2": "Si repites un recorrido, tu mejor marca corre contigo como fantasma y te dice cuánto le sacas o cuánto te saca", "n.race.lb3": "Desde 16 días antes, un tiempo estimado que ya tiene en cuenta el pronóstico del día de la carrera", "n.race.p": "Terminar ante todo, Equilibrio o A por la marca. Elige uno y cambian a la vez cómo se monta tu entrenamiento y cómo te habla mientras corres. Si acabas de empezar, elijas el coach que elijas, no te pondrá series por encima de tu nivel.", "n.race.pb": "Carga el GPX del recorrido y sabrá de antemano dónde empieza cada subida. Envía al reloj el ritmo por tramos ajustado a la pendiente y los puntos de avituallamiento, y el día de la carrera solo tienes que seguir los avisos.", "n.race.sub": "Dile tu carrera objetivo y la marca que buscas, y te prepara la hoja de ruta semana a semana hasta ese día. También te dice sin rodeos si ese objetivo es realista con tu forma actual. Ver el plan es gratis; que el coach te guíe tramo a tramo en el reloj va con la suscripción.", "n.step1h": "Briefing del tiempo", "n.step1p": "Te cuenta el tiempo en directo del barrio donde estás.", "n.step1q": "«Ahora mismo hace 26 grados con un 78 por ciento de humedad. Calor y humedad: la evaporación juega en tu contra.»", "n.step2h": "Calentamiento", "n.step2p": "Un temporizador te lleva fase a fase y, con el coach activado, te va contando en voz alta.", "n.step2q": "«Círculos de tobillo, veinte segundos. Ahora el otro lado. Tres, dos, uno.»", "n.step3h": "Y a correr", "n.step3p": "En cuanto detecta en tu muñeca el ritmo de carrera, empieza a grabar solo.", "n.step3q": "«Has empezado a correr. Empiezo a registrar.»", "n.steps.h": "Pulsas una vez y te olvidas", "n.steps.note": "La pantalla, el temporizador y el inicio automático son gratis. La guía por voz del coach va con la suscripción.", "n.today.eb": "La decisión de hoy", "n.today.h2": "Abres la app por la mañana<br/>y el entreno de hoy ya está decidido", "n.today.h3": "Primero la decisión. Justo debajo, el porqué.", "n.today.l1": "Los días que vas justo, baja la intensidad y te explica por qué", "n.today.l2": "Si aun así quieres hacer el entreno previsto, puedes", "n.today.l3": "Si faltan datos, en lugar de un número verás «Aprendiendo»", "n.today.p": "Arriba del todo, el entreno de hoy. Debajo, por qué lo ha elegido. El resto de métricas quedan más abajo, como referencia. Toca cualquier número y verás qué significa, cómo se calcula y cuál es tu rango habitual.", "n.today.siri": "Ni siquiera tienes que mirar el reloj. Di «Oye Siri, ¿qué corro hoy con Runvis?» y te lee la Decisión de hoy. Tu preparación y el plan de la semana se preguntan igual.", "n.today.sub": "Compara el sueño de anoche, tu VFC (HRV), tu FC en reposo y la carga de ayer con tu rango habitual de los últimos 28 días. Con eso elige el entreno de hoy y te explica el motivo en una línea.", "n.today.w1": "Decisión de hoy", "n.today.w1p": "El anillo de preparación y el entreno de hoy, directamente en la muñeca.", "n.today.w2": "Evidencia de hoy", "n.today.w2p": "Compara sueño, VFC y carga de ayer con lo habitual en ti y los marca como Bueno, Normal o Atención.", "n.today.w3": "Empieza con un toque", "n.today.w3p": "El entreno de hoy aparece arriba del todo en la pantalla de inicio. Tócalo y el coach te guía tramo a tramo.", "n.trust.p": "Runvis lo desarrolla una sola persona. Como aún no ha salido, no hay valoraciones ni artículos de prensa. Si tienes cualquier duda, escribe a help@runvis.app. Te contesto yo en persona.", "n.vc1.aria": "Reproducir voz de ejemplo: aviso de ritmo (gratis)", "n.vc1.line": "\"25 segundos más rápido que el objetivo\"", "n.vc1.play": "Ritmo", "n.vc1.sensor": "📡 Cuando te desvías 20 s o más del ritmo objetivo durante más de 20 segundos", "n.vc2.aria": "Reproducir voz de ejemplo: aviso de cuesta (gratis)", "n.vc2.line": "\"A 300 metros, empieza una subida de 800 metros. Pendiente media del 4 por ciento. Acorta la zancada y mantén el ritmo.\"", "n.vc2.play": "Aviso de cuesta", "n.vc2.sensor": "📡 Lee de antemano el desnivel del recorrido. Si es una ruta que sueles correr, la reconoce hacia los 500 m y te avisa de las cuestas", "n.vc3.aria": "Reproducir voz de ejemplo: aviso de zancada (suscripción)", "n.vc3.line": "\"La cadencia está un 5 por ciento por debajo de tu base — ¿acortamos un poco la zancada?\"", "n.vc3.play": "Zancada", "n.vc3.sensor": "📡 Aviso de zancada · solo en llano y a ritmo constante. Salta si tu cadencia está entre 130 y 160 pasos por minuto y un 5% por debajo de lo habitual durante 30 segundos. También salta si el tiempo de contacto pasa de 300 ms o si la oscilación vertical aumenta (estos dos, con cualquier cadencia). A partir del minuto 6 y como mucho 2 veces por carrera. El ajuste «Técnica» enciende y apaga a la vez este aviso y el de técnica.", "n.vc4.aria": "Reproducir voz de ejemplo: aviso de recuperación (suscripción)", "n.vc4.line": "\"Tu pulso ha bajado hasta la zona 3. Te estás recuperando bien, ya casi.\"", "n.vc4.play": "Recuperación", "n.vc4.sensor": "📡 Cuando recuperas andando y tu zona de FC baja un escalón", "n.why.c1h": "Los sensores ya los llevas en la muñeca", "n.why.c1p": "Pulso, GPS, cadencia y altitud. Los modelos recientes miden incluso el tiempo de contacto y la oscilación vertical.", "n.why.c2h": "Las fórmulas son públicas", "n.why.c2p": "La carga de entrenamiento, el tiempo de recuperación y la estimación del umbral salen de fórmulas públicas muy usadas en ciencias del deporte. Runvis las calcula dentro del reloj y del iPhone.", "n.why.c3h": "Lo que faltaba era el coach", "n.why.c3p": "Alguien que lea los números, decida qué toca hoy y te hable mientras corres. Ese hueco lo llena Runvis.", "n.why.eb": "Por qué Runvis", "n.why.h2": "No necesitas comprar<br/>otro reloj de running", "n.why.sub": "Se suele decir que, para ver la carga de entrenamiento o el tiempo de recuperación, necesitas un reloj de running como un Garmin o un Coros. Pero los sensores que hacen falta para esos cálculos ya los tiene el Apple Watch que llevas en la muñeca.", "nf.title": "Página no encontrada — Runvis", "nf.h1": "Aquí no hay ninguna página", "nf.p": "Puede que el enlace haya cambiado o que la dirección esté mal escrita. Elige abajo adónde quieres ir.", "nf.l1": "Ir al inicio", "nf.l2": "Corre la demo de 5 km", "nf.l3": "Cálculos y herramientas", "ph.email": "Correo electrónico", "pl.coach": "Runvis Coach", "pl.ribbon": "Cuentas con derecho a prueba: 1 mes gratis", "pr.approx": "Precios del App Store de Corea. En otros países se aplica el precio en moneda local que fije el App Store de cada país.", "pr.approxref": "Si nos lees desde fuera de Corea, tómalo solo como referencia aproximada: ₩1,900 al mes son unos 1,30 €; ₩15,000 al año, unos 10 €, y el acceso de por vida de ₩39,000, unos 26 €. Es una conversión orientativa, no lo que se te cobraría.", "pr.free": "Gratis", "pr.launch": "Runvis sale primero en el App Store de Corea y después, poco a poco, en el resto de países. La fecha de lanzamiento se decide cuando termine la beta de TestFlight, y en cuanto la haya, la verás aquí antes que en ningún otro sitio.", "pr.month": "₩1,900", "pv.back": "← Volver a Runvis", "pv.h1": "Política de privacidad", "pv.legalNote": "La versión coreana es el texto legalmente vinculante. Las demás lenguas son traducciones de cortesía; si difieren en su interpretación, prevalece la versión coreana. Contacto: <a href=\"mailto:help@runvis.app\">help@runvis.app</a>", "pv.meta.desc": "Runvis procesa los datos de carrera y salud solo en tu dispositivo. Sin servidor ni cuenta, y aquí están escritas todas las excepciones que salen del dispositivo.", "pv.meta.title": "Política de privacidad — Runvis", "pv.s1.h": "1. Datos que se recogen y tratan", "pv.s1.li1": "<b>Datos de entrenamiento</b>: frecuencia cardiaca, ritmo, distancia, ruta GPS, altitud, cadencia, potencia de carrera, longitud de zancada, tiempo de contacto y oscilación vertical (en dispositivos compatibles), calorías — leídos y guardados a través de Apple HealthKit", "pv.s1.li2": "<b>Datos de salud</b>: sueño (duración y fases), variabilidad de la frecuencia cardiaca (VFC), pulso en reposo, VO₂max y, si lo eliges, ciclo menstrual — se usan para el análisis de preparación y recuperación", "pv.s1.li3": "<b>Datos de movimiento</b>: aceleración de la muñeca (para detectar automáticamente el inicio de la carrera) y, si los llevas puestos, el movimiento de cabeza de los AirPods — como señal de apoyo para la técnica", "pv.s1.li4": "<b>Datos de perfil</b>: año de nacimiento, sexo, pulso en reposo y frecuencia cardiaca máxima — los introduces tú en la pantalla de configuración inicial y solo se usan como base de las zonas de pulso y de las estimaciones por edad", "pv.s1.li5": "<b>Otros datos introducidos</b>: carrera y marca objetivo, tono del coach, información de las zapatillas y el check-in posterior (esfuerzo, dolor, hidratación)", "pv.s1.li6": "<b>Sensores Bluetooth</b>: si están conectados, las lecturas en directo de una banda de pulso, un potenciómetro de ciclismo o un rodillo inteligente", "pv.s1.li7": "<b>Datos de diagnóstico</b>: informes de fallos y bloqueos (Apple MetricKit) — se guardan solo en el dispositivo y salen de él únicamente si tú los exportas o compartes", "pv.s1.p": "Runvis lee y trata los siguientes datos <b>dentro del dispositivo</b>. Todos sirven para el funcionamiento de la app y ninguno sale del dispositivo.", "pv.s10.h": "10. Cambios y contacto", "pv.s10.p": "Cuando esta política cambie, se actualizará la fecha de entrada en vigor de esta página. Para las condiciones del servicio, consulta los <a href=\"terms.html\">Términos de servicio</a>. Contacto: <a href=\"mailto:help@runvis.app\">help@runvis.app</a>", "pv.s2.h": "2. Dónde se guardan los datos", "pv.s2.li1": "Los entrenamientos y las rutas se guardan en <b>Salud (HealthKit)</b>: son tuyos, y que se sincronicen por iCloud Salud depende de tus ajustes de iOS", "pv.s2.li2": "Los ajustes de la app, los datos de perfil, los planes, los recorridos y el cálculo de las insignias se guardan <b>solo en el almacenamiento local de la app</b>", "pv.s2.li3": "Runvis no opera ningún servidor, base de datos ni sistema de cuentas propio", "pv.s2.li4": "Runvis no hace copia de seguridad ni sincronización propias. Al cambiar de dispositivo, los entrenamientos guardados en Salud de Apple te acompañan, pero los valores que solo viven en el almacenamiento de la app —perfil, zapatillas, plan, insignias y las líneas base creadas por el entrenador— no. En Ajustes → Datos, «Exportar mis datos» reúne esos valores en un único archivo que «Importar desde copia» restaura en el dispositivo nuevo; ese archivo se queda solo donde tú lo pongas y Runvis no lo envía a ninguna parte", "pv.s3.h": "3. Todo lo que sale del dispositivo (lista completa)", "pv.s3.note": "Ninguno de los casos anteriores incluye información identificativa como nombre o correo electrónico, y Runvis no lleva un registro aparte. Runvis <b>no sube</b> los datos de entrenamiento y salud que registra: la app no contiene código para hacerlo, y todas las peticiones anteriores son consultas de solo lectura con la información mínima imprescindible.", "pv.s3.r1a": "Informe del tiempo", "pv.s3.r1b": "Coordenadas redondeadas a aproximadamente 1 km (precisión de barrio) y la hora — solo en el momento de la consulta, sin almacenamiento ni identificador", "pv.s3.r1c": "Open-Meteo (API meteorológica gratuita)", "pv.s3.r2a": "Pago de la suscripción", "pv.s3.r2b": "Todo el proceso de pago: Runvis no puede ver ni guardar los datos de la tarjeta o del pago", "pv.s3.r2c": "Apple App Store", "pv.s3.r3a": "Generación automática de recorridos", "pv.s3.r3b": "Tus coordenadas actuales para calcular la ruta — solo en el momento en que la pides, y sin redondear", "pv.s3.r3c": "Apple Mapas (MapKit)", "pv.s3.r4a": "Nombre del barrio", "pv.s3.r4b": "Tus coordenadas actuales, para que el informe del tiempo y el registro de la carrera lleven el nombre del barrio — solo en el momento de la consulta, y sin redondear. El resultado se guarda en caché en el dispositivo, así que un mismo lugar no se consulta dos veces", "pv.s3.r4c": "Servicios de localización de Apple (CLGeocoder)", "pv.s3.r5a": "Descarga del catálogo de recorridos y zapatillas", "pv.s3.r5b": "<b>No se envía nada</b>: se descarga de forma anónima un archivo público una vez al día (como en cualquier visita web, tu IP es visible para el servidor)", "pv.s3.r5c": "GitHub Pages (alojamiento de archivos estáticos)", "pv.s3.r6a": "Abrir una búsqueda de zapatillas", "pv.s3.r6b": "<b>No se envía nada</b> — solo si tocas tú el botón en la pantalla de zapatillas del reloj o del iPhone se abre un navegador externo en una dirección con el término de búsqueda «zapatillas de running». No sale ningún dato de entrenamiento, salud ni zapatillas", "pv.s3.r6c": "Una tienda externa: por ahora la página de búsqueda del comercio coreano Coupang", "pv.s3.th1": "Excepción", "pv.s3.th2": "Qué se envía", "pv.s3.th3": "Destinatario", "pv.s4.h": "4. Para qué se usa cada permiso", "pv.s4.li1": "<b>Salud (HealthKit)</b>: guardar los entrenamientos y analizar el historial", "pv.s4.li2": "<b>Ubicación</b>: registrar la ruta, el informe del tiempo y la guía del recorrido", "pv.s4.li3": "<b>Movimiento</b>: detectar automáticamente el inicio de la carrera y guiar el calentamiento", "pv.s4.li4": "<b>Notificaciones</b> (opcional, 9 tipos): recordatorios de los días del plan, el informe de la tarde, el resumen semanal del coach del domingo, un aviso de vuelta tras una larga pausa, una nota de la primera semana tras suscribirte, un aviso dos días antes de que acabe la prueba gratuita o el modo coach, una invitación a volver a suscribirte una semana después de cancelar (esa es publicidad), el aviso de recuperación completa del reloj y el aviso de descanso del reloj — el texto se compone en el dispositivo y nunca se envía a un servidor", "pv.s4.li5": "<b>Bluetooth</b>: conectar sensores externos (bandas de pulso, potenciómetros)", "pv.s4.li6": "<b>Calendario</b> (opcional): añadir las sesiones del plan a tu calendario", "pv.s4.li7": "<b>Fotos</b> (opcional): guardar el vídeo de sobrevuelo de la ruta", "pv.s4.note": "Puedes rechazar cualquier permiso: solo se ve afectada esa función concreta y el resto de la app sigue funcionando.", "pv.s5.h": "5. Terceros, publicidad y rastreo", "pv.s5.li1": "Cesión a terceros: <b>ninguna</b> — se refiere a los datos de entrenamiento y salud que trata la app. La única excepción es el correo de solicitud de la beta en la web, encargado a Formspree y descrito en el apartado 6", "pv.s5.li2": "SDK de publicidad, SDK de analítica y herramientas de rastreo: <b>ninguno</b>", "pv.s5.li3": "Venta de datos: <b>ninguna</b>", "pv.s6.h": "6. El sitio web (solicitud de beta)", "pv.s6.li1": "<b>Qué se recoge</b>: la dirección de correo, únicamente la que tú escribes", "pv.s6.li2": "<b>Finalidad</b>: enviar la invitación a la beta de TestFlight y los avisos relacionados con la beta", "pv.s6.li3": "<b>Encargado del tratamiento y transferencia internacional</b>: el envío y el almacenamiento del formulario están encargados a <b>Formspree, Inc.</b> (EE. UU.), de modo que la dirección que envías se transmite y se conserva en servidores de Formspree en Estados Unidos — <a href=\"https://formspree.io/legal/privacy-policy/\" rel=\"noopener\">política de privacidad de Formspree</a>", "pv.s6.li4": "<b>Conservación y supresión</b>: se elimina sin demora en cuanto se cumple la finalidad (enviada la invitación a la beta) y, en todo caso, en el plazo de un año desde su recogida. Para solicitar la supresión: <a href=\"mailto:help@runvis.app\">help@runvis.app</a>", "pv.s6.p": "Si envías una dirección de correo a través del formulario de beta de runvis.app, se trata como sigue. Este apartado solo se aplica al formulario de la web; la app no recoge ninguna información de cuenta, tampoco el correo.", "pv.s7.h": "7. Borrado de datos", "pv.s7.p": "Al borrar la app se elimina todo lo que hay en su almacenamiento, incluidos los datos de perfil. Los entrenamientos guardados en HealthKit son tuyos, así que permanecen en la app Salud aunque desinstales Runvis; puedes borrarlos allí tú mismo.", "pv.s8.h": "8. Menores", "pv.s8.p": "Runvis no está dirigido a menores de 14 años. La pantalla de configuración inicial pide el año de nacimiento para calcular las zonas de pulso y las estimaciones por edad, pero ese dato se guarda solo en el dispositivo y nunca se transmite. Si un menor la usa a través de Compartir en familia con el acceso de por vida, se requiere supervisión parental.", "pv.s9.h": "9. Aviso médico", "pv.s9.p": "Todas las cifras y avisos de Runvis son <b>estimaciones orientativas</b> basadas en fórmulas publicadas de ciencias del deporte, y no constituyen diagnóstico, tratamiento ni prescripción médica. Si notas síntomas como dolor torácico o mareo, detén el ejercicio de inmediato y consulta a un profesional.", "pv.summary": "<b>En un párrafo</b> — Runvis procesa tus datos de carrera y salud <b>solo dentro de tu dispositivo</b>. No hay servidor de Runvis ni cuenta, y tus datos de entrenamiento y salud nunca se transmiten, venden ni comparten con nadie, tampoco con el desarrollador. Abajo se detallan todas las excepciones (consulta del tiempo, pagos de Apple, generación de rutas en el mapa, consulta del nombre del barrio, descarga de los archivos públicos de recorridos y zapatillas, y el enlace de búsqueda de zapatillas que tocas tú).", "pv.updated": "En vigor: 2 de octubre de 2026 · versión 1.4", "r.alt.elev": "Perfil de altimetría de los próximos 1,5 kilómetros: la subida empieza a 300 metros y acumula 34 metros de desnivel positivo", "r.alt.watch": "Pantalla del Apple Watch: objetivo de hoy, 5,0 kilómetros; Correr con Runvis", "r.badge.note": "Cada frase del coach lleva su etiqueta: <span class=\"pill free\">Gratis</span> o <span class=\"pill pro\">Suscripción</span>. Grabar, marcar vueltas, guardar en Salud, ver tu historial y tu plan de entrenamiento, consultar el informe detallado del entreno y usar la pantalla de calentamiento: todo eso es gratis.", "r.hud.dist": "DIST", "r.hud.hr": "FC", "r.hud.pace": "RITMO", "r.hud.zone": "ZONA", "r.rail.aria": "Tramos de la sesión de carrera", "r.signup.h": "Has corrido los 5 km enteros", "r.signup.p": "¿Quieres oír en tu muñeca los avisos que acabas de leer? Apúntate aquí mismo. Cuando haya fecha de apertura, te avisaremos primero en esta dirección, y las invitaciones salen por orden de inscripción.", "r.signup.price": "Ver precios", "r.tier.free": "Grabación GPS, vueltas, guardado en Salud y todo tu historial · ver el plan de entrenamiento · informe detallado del entreno · pantalla de calentamiento · corriendo con el reloj, voz de parciales por km (o milla), zonas de FC, ritmo, aviso de cuestas del recorrido y alerta de desvío de ruta (solo con el iPhone, la única voz gratis son los parciales) · tarjeta de consejo al terminar · Modo carrera y fantasma en pantalla", "r.tier.price": "Elige: ₩1,900 al mes, suscripción anual o acceso de por vida. Los precios son los del App Store. No hay cuenta ni servidor: tus datos se quedan en tu dispositivo y en Salud.", "r.tier.pro": "Voz del coach para la técnica, cómo subir cuestas, la recuperación y el ánimo · el plan de entrenamiento tramo a tramo, con puntuación frente al plan al terminar · 8 paneles de análisis a fondo · estrategia de carrera (ensayo, plan de ritmos por tramo, plan de avituallamiento) · tarjeta «Tu semana con el coach»", "r.unitnote": "Esta demo solo corre en kilómetros. La app de verdad sigue la unidad de tu dispositivo: te canta los parciales cada 1 km o cada 1 milla, y las distancias y ritmos de la pantalla y de la voz salen en esa unidad.", "r.silence": "{km} km hasta el siguiente aviso · en este tramo el coach solo te canta los parciales de 1 km", "r.warmup.v": "6 PASOS", "r1": "RUN SESSION — 5 km con Runvis | Runvis", "r10": "RUNVIS // LIVE COACHING DEMO", "r11": "Hoy sales a correr<br><span class=\"outline\">con tu coach</span>.", "r12": "A partir de aquí, <b>hacer scroll es correr</b>. Baja y empiezan tus 5 km: la distancia, el ritmo y el pulso de abajo se mueven contigo. Descubre <b>cuándo y por qué te habla Runvis</b>, y cuándo se calla.", "r13": "Las cifras de pantalla son de ejemplo para la demo · la app real funciona con los sensores del Apple Watch", "r14": "kilómetros · objetivo de hoy", "r15": "Correr con Runvis", "r16": "Briefing · calentamiento · coaching", "r17": "SEGMENT 00 — EN LA PUERTA · 05:52 AM", "r18": "Antes de correr,<br><span class=\"grad\">el coach ya se ocupa de ti</span>", "r19": "Con un solo botón se encadenan <b>briefing del tiempo → calentamiento</b>. Sin servidores propios, dentro del reloj.", "r2": "Aquí, hacer scroll es correr. Del calentamiento a la meta, recorre 5 km y escucha cuándo y por qué te habla el coach de Runvis.", "r20": "«Hola, soy Runvis. ¿Corremos juntos hoy? Este es el tiempo ahora en Yeouido-dong. Ahora mismo hace 26 grados con un 78 por ciento de humedad. Calor y humedad: la evaporación juega en tu contra. Como punto de partida, bebe unos sorbos cada quince minutos más o menos, aproximadamente cada tres kilómetros, y ajústalo según la sed y lo que sudas. Fin del resumen. Pulsa Empezar calentamiento en pantalla y soltamos el cuerpo.»", "r21": "WHY · <b>El nombre de tu barrio + el tiempo en directo de Open-Meteo</b>, y con eso, cuánto beber según la temperatura y la humedad. Los días de calor, además, los avisos para beber llegan más a menudo durante la carrera, de forma automática. La pantalla del tiempo y el temporizador de calentamiento son gratis; lo que va con la suscripción es que <b>te lo lea en voz alta</b>", "r22": "Ojo: para el tiempo se envían coordenadas redondeadas a Open-Meteo, y para mostrar el nombre del barrio, tus coordenadas actuales a los servicios de localización de Apple. Solo en ese momento.", "r23": "SEGMENT 01 — 0.0 → 1.0 KM", "r24": "No tienes que pulsar nada.<br><span class=\"outline\">Echas a correr y lo nota</span>", "r25": "Acabas el calentamiento, echas a correr y Runvis <b>detecta la carrera solo</b>: empieza a grabar y a guiarte.", "r26": "«Informe de condición de hoy. Has dormido 7 horas y 24 minutos. Tu pulso en reposo está por debajo de lo habitual: buena señal.»", "r27": "WHY · El ritmo del acelerómetro de tu muñeca <b>detecta la carrera automáticamente</b> y empieza a grabar (gratis) · El informe de condición llega 8 segundos después de arrancar, y solo si tu FC en reposo está 5 por encima o 3 por debajo de lo habitual, o si has dormido menos de 6 horas. Un día normal, no dice nada", "r28": "−4 (POR DEBAJO)", "r29": "SEGMENT 02 — 1.0 → 2.5 KM · SUBIDA", "r3": "START", "r30": "Una cuesta <span class=\"grad\">que ves venir</span><br>ya no asusta", "r31": "Carga el GPX de tu carrera y Runvis te avisa de <b>la subida que aún no ves</b>.", "r32": "«En 300 metros empieza una subida de 800 metros. Pendiente media del 4 por ciento. Acorta la zancada y mantén el ritmo.»", "r33": "WHY · Lee de antemano el desnivel del recorrido. Con el coach activado, en las subidas también te dice, con el <b>ritmo ajustado a la pendiente</b>, si vas bien de velocidad", "r34": "SEGMENT 03 — 3.0 → 4.0 KM · LLEGA LA FATIGA", "r35": "Cuando empieza a costar,<br>te habla <span class=\"outline\">con datos</span>", "r36": "No un «vas mal de postura», sino un aviso de técnica que te dice <b>qué ha cambiado y cuánto</b>.", "r37": "«Tus pasos son un 7 por ciento más lentos y pisas un 10 por ciento más tiempo que al empezar. Acorta la zancada: recuperas la frecuencia y con ella la técnica.»", "r38": "WHY · El aviso de técnica no es el de zancada y tiene sus propias reglas · Relojes que miden contacto y oscilación vertical: salta si, entre cadencia, contacto y oscilación, <b>dos o más se descolocan a la vez</b> o una se descoloca mucho, durante 30 segundos · Relojes que solo miden cadencia: la cadencia cae un 6% durante 60 segundos · En ambos casos, solo en llano y a ritmo constante · El ajuste «Técnica» activa a la vez este aviso y el de zancada · Una vez dicho, no lo repite hasta que la desviación remite", "r39": "«Muy bien, la postura está volviendo. Mantén esa sensación un poquito más.»", "r4": "BRIEFING", "r40": "WHY · Solo en carreras en las que <b>de verdad oíste el aviso</b> · Una vez, cuando han pasado 2 minutos desde el aviso y la desviación ha bajado claramente respecto a su peor momento. Si la regla de separación entre avisos no dejó que sonara, tampoco te felicita", "r41": "SEGMENT 04 — 4.0 → 4.5 KM · PAUSA ANDANDO", "r42": "Andar también es<br><span class=\"grad\">parte del entreno</span>", "r43": "Si te fundes, anda un rato, no pasa nada. Runvis no te echa la bronca por parar: <b>te acompaña en la recuperación</b>.", "r44": "«Has empezado a caminar; recuperar el aliento es buena idea. Vuelve a trotar cuando te encuentres bien, o sigue caminando si lo necesitas. Te aviso cuando tu pulso baje a la zona uno.»", "r45": "WHY · Si la velocidad baja a ritmo de paseo y la <b>cadencia se queda por debajo de 130 durante 8 segundos</b>, entiende que andas. Solo al aire libre con GPS, a partir del minuto 5 y en carrera libre, no en un plan · Cuando empiezas a andar, descarta los avisos de carrera que tenía en cola", "r46": "138 ← ahora", "r47": "EN ESPERA…", "r48": "«Tu pulso se ha recuperado. ¿Volvemos a correr despacio? Empieza suave.»", "r49": "WHY · Mientras andas, te avisa <b>cada vez que bajas una zona de FC</b>, y cuando llegas a la zona 1 te dice que ya puedes volver a correr. Oyes <b>cómo te recuperas</b>", "r5": "SALIDA", "r50": "FINISH — 5.0 KM · MISSION COMPLETE", "r51": "La carrera ha terminado.<br>El coaching <span class=\"grad\">empieza ahora</span>", "r52": "En cuanto se guarda la carrera, te llegan las zonas de FC, la carga de entrenamiento y lo que ha visto en tu técnica, con un <b>resumen de coaching para tu próxima salida</b>. Todo esto es gratis. Si quieres, con un toque exportas un informe para pasárselo a la IA que uses.", "r53": "Distancia · Tiempo", "r54": "Ritmo medio · pulso", "r55": "Carga de entrenamiento", "r56": "TRIMP 54 · deriva +1,8 %", "r57": "La frase del coach", "r58": "La eficiencia cardiaca se mantuvo hasta la segunda mitad.", "r59": "Exportar", "r6": "SUBIDA", "r60": "✨ Para análisis con IA · GPX", "r62": "Ver todas las funciones", "r63": "Las cifras y frases de esta página son ejemplos para mostrar cómo funciona la app real. Todas las métricas e indicaciones son información de referencia basada en fórmulas generales de ciencias del ejercicio, no consejo médico.<br>Contacto: <a href=\"mailto:help@runvis.app\" style=\"color:var(--dim)\">help@runvis.app</a> · © 2026 Runvis · Apple Watch es una marca de Apple Inc.", "r7": "EL MURO", "r8": "RECUPERACIÓN", "r9": "META", "sc.note": "Las 5 pantallas de iPhone y las 6 de Apple Watch de esta página son capturas reales, hechas con la app en español. Las pantallas en carrera se tomaron durante una carrera real. Desde entonces la app se ha seguido puliendo, así que la versión que instales puede ser más nueva que lo que ves aquí.", "sc.note.s": "Capturas reales de la app en español.", "t160": "Quiero la invitación a la beta", "t161": "Qué recopilamos", "t162": "Periodo de conservación", "t163": "Política de privacidad", "t164": "Términos del servicio", "t165": "help@runvis.app", "t166": "Todas las métricas e indicaciones de Runvis son información de referencia basada en fórmulas generales de ciencia del ejercicio; no son consejo médico ni evalúan tu estado de salud. Si presentas síntomas como dolor en el pecho o mareos, deja de hacer ejercicio y consulta a un profesional. Apple Watch es una marca comercial de Apple Inc. Runvis es una app independiente y no está afiliada a Apple.", "tm.back": "← Volver a Runvis", "tm.h1": "Términos de servicio", "tm.legalNote": "La versión coreana es el texto legalmente vinculante. Las demás lenguas son traducciones de cortesía; si difieren en su interpretación, prevalece la versión coreana. Contacto: <a href=\"mailto:help@runvis.app\">help@runvis.app</a>", "tm.meta.desc": "Términos de servicio de Runvis: suscripciones y pase de por vida, renovación automática y cancelación, avisos de seguridad y límites de responsabilidad.", "tm.meta.title": "Términos de servicio — Runvis", "tm.s1.h": "1. Descripción del servicio", "tm.s1.p": "Runvis es una app de registro y coaching de carrera para Apple Watch y iPhone. La grabación GPS, las vueltas, el guardado en Salud, la consulta del historial, la vista del plan de entrenamiento, el informe detallado de la carrera y la pantalla de calentamiento son gratis. El coaching por voz de técnica, recuperación y ánimo, la ejecución del plan tramo a tramo con puntuación de cumplimiento, el análisis profundo, la estrategia de carrera y el resumen semanal del coach se ofrecen mediante suscripción dentro de la app o un pase de por vida. Runvis no crea cuentas ni opera servidor propio.", "tm.s2.h": "2. Suscripciones", "tm.s2.li1": "El pago, la renovación y la cancelación se gestionan a través de tu cuenta del App Store de Apple y siguen las condiciones estándar de suscripción de Apple", "tm.s2.li2": "Los planes mensual y anual son de <b>renovación automática</b>. Si no cancelas al menos <b>24 horas antes</b> del fin del periodo en curso, la suscripción se renueva sola y el cargo se aplica a tu cuenta de Apple dentro de las 24 horas previas al fin del periodo", "tm.s2.li3": "Cuando se ofrece una prueba gratuita, esta pasa a suscripción de pago y se cobra si no cancelas al menos 24 horas antes de que termine. Que haya prueba lo determina Apple según la elegibilidad de tu cuenta, y solo aparece en la pantalla de compra si eres elegible", "tm.s2.li4": "Puedes cancelar cuando quieras en Ajustes de iOS → Cuenta de Apple → Suscripciones, y conservas el acceso hasta que termine el periodo ya pagado", "tm.s2.li5": "Las suscripciones mensual y anual no están cubiertas por Compartir en familia de Apple. El único producto que un grupo familiar puede compartir es el acceso de por vida del apartado 3", "tm.s2.li6": "Los reembolsos siguen la política y el procedimiento de reembolso de Apple", "tm.s3.h": "3. Pase de por vida", "tm.s3.li1": "El pase de por vida es un <b>producto no consumible de pago único</b>, sin renovación automática. Desbloquea las mismas funciones de coaching que la suscripción", "tm.s3.li2": "El precio actual es un <b>precio de lanzamiento</b> y puede subir más adelante. La subida se aplica <b>solo a las compras posteriores</b>; un pase ya adquirido no vuelve a cobrarse", "tm.s3.li3": "El acceso de por vida está cubierto por Compartir en familia de Apple, así que los miembros de tu grupo familiar también pueden usarlo; ninguna de las suscripciones se comparte", "tm.s3.li4": "Como Runvis no crea cuentas, en un dispositivo nuevo o tras reinstalar recuperas el pase con <b>Restaurar compras</b> en la pantalla de compra. La restauración solo funciona con la cuenta de Apple usada en la compra", "tm.s3.li5": "El pase de por vida es válido mientras la app Runvis se ofrezca en el App Store. Si el servicio se interrumpe, se aplica además la cláusula de límites del servicio del apartado 5", "tm.s3.li6": "Los reembolsos siguen la política y el procedimiento de reembolso de Apple", "tm.s3.li7": "El bote de propinas (café, comida, corazón) es un <b>agradecimiento puntual</b> y no desbloquea ninguna función: no sustituye a la suscripción ni al pase de por vida", "tm.s4.h": "4. Responsabilidades del usuario", "tm.s4.li1": "Ejercítate según tu propio criterio y bajo tu responsabilidad, teniendo en cuenta tu estado de salud", "tm.s4.li2": "Al correr al aire libre por carretera o pista, presta atención en todo momento al tráfico y al entorno, y usa la guía por voz a un volumen que no tape el sonido ambiente", "tm.s4.li3": "Si notas síntomas como dolor torácico, mareo o dificultad para respirar, detén el ejercicio de inmediato y consulta a un profesional", "tm.s5.h": "5. Límites del servicio y exención de responsabilidad", "tm.s5.li1": "Todas las cifras, predicciones e indicaciones de Runvis son <b>información orientativa</b> basada en fórmulas publicadas de ciencias del deporte, y no constituyen diagnóstico, tratamiento ni prescripción médica", "tm.s5.li2": "Por la naturaleza de los sensores, las mediciones de pulso, GPS y dinámica de carrera pueden tener error, y no se garantiza su exactitud", "tm.s5.li3": "El desarrollador no asume responsabilidad legal por los resultados del entrenamiento basado en esta información orientativa (cambios en las marcas, lesiones, etc.), salvo por los daños causados por dolo o negligencia grave", "tm.s5.li4": "El servicio se ofrece \"tal cual\", y algunas funciones pueden cambiar o dejar de funcionar si cambian la plataforma de Apple o las API externas (el tiempo, por ejemplo)", "tm.s6.h": "6. Propiedad intelectual", "tm.s6.p": "El diseño, los textos y el código de la app y del sitio web pertenecen al desarrollador. Tus datos de entrenamiento y salud son enteramente tuyos.", "tm.s7.h": "7. Cambios en estos términos", "tm.s7.p": "Cuando estos términos cambien, se actualizará la fecha de entrada en vigor de esta página, y los cambios importantes se anunciarán dentro de la app.", "tm.s8.h": "8. Contacto", "tm.s8.p": "<a href=\"mailto:help@runvis.app\">help@runvis.app</a> · Para saber cómo se tratan tus datos, consulta la <a href=\"privacy.html\">Política de privacidad</a>.", "tm.updated": "En vigor: 6 de septiembre de 2026 · versión 1.2", "vchip0": "25 segundos más rápido que el objetivo", "vchip1": "A 300 metros, empieza una subida de 800 metros. Pendiente media del 4 por ciento. Acorta la zancada y mantén el ritmo.", "vchip2": "La cadencia está un 5 por ciento por debajo de tu base — ¿acortamos un poco la zancada?", "vchip3": "Tu pulso ha bajado hasta la zona 3. Te estás recuperando bien, ya casi.", "pl.month": "Mensual", "pl.year": "Anual", "pl.life": "De por vida", "pr.year": "₩15,000", "pr.life": "₩39,000", "pr.monthn": "Se renueva cada mes · cancela cuando quieras", "pr.yearn": "Unos ₩1,250 al mes · alrededor de un 34% menos que el mensual", "pr.lifen": "Pago único · sin renovación automática · Compartir en familia de Apple", "n.price.moreh": "Precios en otros países, ahorro y cuándo sale a cuenta", "n.price.nowh": "Se activa en cuanto te suscribes", "n.price.laterh": "Se completa a medida que acumulas carreras", "n.price.f6": "Tarjeta de consejo al terminar de correr", "n.beta.order": "Aún no hay fecha de apertura. Las invitaciones salen por orden de inscripción. Apple fija un tope de 10.000 probadores externos en TestFlight, así que cuanto antes te apuntes, antes te llegará la invitación.", "hz.h": "Calcúlalo ahora: tus 5 zonas de FC", "hz.p": "Es la misma fórmula de Karvonen que usa Runvis para la voz del coach. En la app, estos valores se actualizan solos con la FC en reposo de tus últimos 7 días en Salud y la FC más alta que se te ha registrado de verdad, pero el cálculo es este.", "hz.age": "Edad", "hz.rest": "FC en reposo", "hz.max": "FC máxima (si no la sabes, déjala en blanco)", "hz.bpm": "ppm", "hz.note": "Límite inferior de cada zona = (FC máx − FC en reposo) × 50/60/70/80/90% + FC en reposo. Si dejas la máxima en blanco, se estima con 208 − 0,7 × edad. Es un cálculo orientativo, no un consejo médico.", "hz.bad": "Tu FC en reposo está demasiado cerca de la máxima para poder repartir las zonas.", "hz.z1": "Z1 Recuperación", "hz.z2": "Z2 Aeróbico", "hz.z3": "Z3 Tempo", "hz.z4": "Z4 VO2max", "hz.z5": "Z5 Anaeróbico", "hz.maxtyped": "Con la FC máxima que has introducido", "hz.maxest": "FC máxima estimada con 208 − 0,7 × edad", "form.okaddr": "Dirección registrada", "r.cue": "Haz scroll para salir ▾", "pr.approx2": "Esas conversiones son aproximadas, para que te hagas una idea; no es lo que se te cobraría. Apple no cobra según el tipo de cambio, sino por tramos de precio que fija para cada país, así que la cifra real quedará algo por encima o por debajo. Cuando se fijen los precios de otros países, pondremos aquí las cifras reales. La pantalla de compra de la app no adivina: muestra tal cual el precio de tu país que le da la tienda.", "hw.meta.title": "Frente a Garmin y Coros: cómo se calcula cada métrica | Runvis", "hw.meta.desc": "El Apple Watch frente a relojes de running dedicados como Garmin Forerunner o Coros, métrica a métrica, y cómo calcula Runvis la carga de entrenamiento, el tiempo de recuperación y el umbral de lactato. Además: cuántas veces habla el coach cada 30 minutos, calculadora de zonas de FC, 13 recorridos de Seúl en GPX y cómo funciona la beta.", "hw.h1": "Cálculos y herramientas", "hw.intro": "Aquí tienes en detalle lo que la portada resume en una línea. Puedes leerlo y probarlo ya, sin apuntarte y sin instalar la app.", "hw.s1.h": "Cuántas veces habla el coach, y las excepciones", "hw.vs.h": "¿En qué se parece a un reloj de running como un Garmin Forerunner o un Coros, y en qué se diferencia?", "hw.vs.p": "Carga de entrenamiento, tiempo de recuperación, umbral de lactato estimado, plan de ritmos para la carrera. Se suele decir que para ver estos datos necesitas un reloj de running como un Garmin Forerunner o un Coros. Hay marcas que ya los calculan dentro de sus propios relojes; solo que nadie lo hacía en el Apple Watch. Runvis calcula esos mismos valores con el pulso, el GPS y la altitud que tu Apple Watch ya ha registrado. Los relojes dedicados no publican sus fórmulas, así que no vamos a decir que son «las mismas». Lo que sí te decimos es que todas las que usa Runvis son fórmulas públicas con nombre propio, y abajo las tienes nombradas. En la app, cada métrica se abre con un toque y te enseña qué significa, de dónde sale y cuál es tu rango habitual.", "hw.vs.th1": "Métrica", "hw.vs.th2": "Cómo lo calcula Runvis y con qué fórmula", "hw.vs.r12a": "Volumen de entrenamiento de resistencia", "hw.vs.r12b": "Un valor de 0 a 100 que mezcla tres datos de los últimos 28 días en proporción 45 : 35 : 20: distancia semanal (con 80 km a la semana, puntuación máxima), tu carrera más larga (con 30 km, puntuación máxima) y en cuántas de las últimas 4 semanas has corrido. No puntúa al corredor: muestra el volumen de entrenamiento que llevas acumulado ahora. Si faltan datos, no se inventa la cifra: se queda en 0 y la pantalla te dice qué falta.", "hw.vs.r13a": "Carga en las piernas", "hw.vs.r13b": "La carga que una carrera deja en tus piernas, contada en «km equivalentes». 1 km llano y suave vale 1,0; la misma distancia corrida rápido, en subida o en bajada, cuenta más. El cálculo: 1 carrera = distancia × multiplicador de intensidad × multiplicador de pendiente. El multiplicador de intensidad lo marca la velocidad, no el pulso (frente a tus ritmos suave y de umbral): 1,0 a ritmo suave o más lento, 1,35 en umbral y, si vas más rápido, hasta 1,6. El multiplicador de pendiente, en subida, es ritmo real ÷ ritmo ajustado a la pendiente (máximo 1,6); en bajada cuenta más, con 1 + 1,2 × (1 − esa proporción) (máximo 2,0), porque bajar cansa menos pero castiga más. El valor a corto plazo es una media móvil exponencial diaria (EWMA, constante de tiempo de 7 días), así que está en escala de media diaria (si corres con regularidad, más o menos el total semanal ÷ 7); el semanal es la suma simple de esa semana. Aparece en el panel del informe y en el detalle de cada carrera (al lado de «Carga de entrenamiento (TRIMP)»), junto a la distancia real. Todavía no tiene en cuenta la dinámica de carrera ni los tramos andando. Garmin no ha publicado su fórmula; los multiplicadores de arriba son valores de referencia que ha fijado Runvis a partir de la literatura publicada.", "hw.vs.r1a": "Carga de entrenamiento · frescura (TSB)", "hw.vs.r1b": "El TRIMP de Banister entra en las medias móviles exponenciales de 42 y 7 días de Coggan (CTL y ATL). El TSB de hoy es el CTL de ayer menos el ATL de ayer (según la definición de Coggan, la carga de hoy no cambia el TSB de hoy).", "hw.vs.r2a": "Tiempo de recuperación", "hw.vs.r2b": "Se estima con tres datos: el TRIMP de tu última carrera, tu TSB actual y la Tendencia de la VFC. La pantalla también lo marca como estimado.", "hw.vs.r3a": "Umbral de lactato (est.)", "hw.vs.r3b": "El ritmo y el pulso de tu mejor tramo de 30 minutos (o de 20) aguantado al 85% o más de tu FC máxima en los últimos 90 días. Es una estimación sacada de tus carreras, no un análisis de sangre en laboratorio.", "hw.vs.r4a": "Predicción de carrera · plan de ritmos por tramo", "hw.vs.r4b": "Predice con la fórmula de Riegel y el índice de forma de Runvis. Si cargas el GPX del recorrido, reparte el ritmo tramo a tramo según el desnivel de ese recorrido.", "hw.vs.r5a": "Ritmo ajustado a la pendiente (GAP)", "hw.vs.r5b": "Usa la curva de coste energético de la carrera de Minetti (2002). Calcula por separado lo que cuesta subir y lo que cuesta bajar.", "hw.vs.r6a": "5 zonas de FC", "hw.vs.r6b": "Método Karvonen (reserva de frecuencia cardiaca). Si no sabes tu FC máxima, se estima con 208 − 0,7 × edad. La calculadora de abajo usa la misma fórmula.", "hw.vs.note": "Y lo que tienen los relojes dedicados y Runvis aún no, también lo decimos: esta versión no trae complicaciones para la esfera, ni widget en la pantalla de inicio del iPhone, ni Actividades en directo. Todos los valores de arriba son información de referencia, no consejo médico."};
if(window.RunvisOnDict)window.RunvisOnDict("es");
